DELIMITER $$
DROP PROCEDURE IF EXISTS sp_fail$$
CREATE PROCEDURE sp_fail(IN p_code VARCHAR(30)) BEGIN CASE p_code
WHEN 'E_FORBIDDEN' THEN SIGNAL SQLSTATE '45001' SET MESSAGE_TEXT='E_FORBIDDEN: Actor is not authorized for this action.';
WHEN 'E_NOT_FOUND' THEN SIGNAL SQLSTATE '45002' SET MESSAGE_TEXT='E_NOT_FOUND: Referenced record does not exist.';
WHEN 'E_INPUT' THEN SIGNAL SQLSTATE '45003' SET MESSAGE_TEXT='E_INPUT: Input violates the declared field contract.';
WHEN 'E_DUPLICATE' THEN SIGNAL SQLSTATE '45004' SET MESSAGE_TEXT='E_DUPLICATE: Unique identity already exists.';
WHEN 'E_AMOUNT' THEN SIGNAL SQLSTATE '45005' SET MESSAGE_TEXT='E_AMOUNT: Amount must satisfy the operation minimum and scale.';
WHEN 'E_FUNDS' THEN SIGNAL SQLSTATE '45006' SET MESSAGE_TEXT='E_FUNDS: Wallet has insufficient available balance.';
WHEN 'E_FROZEN' THEN SIGNAL SQLSTATE '45007' SET MESSAGE_TEXT='E_FROZEN: Issue escrow is frozen by an open dispute.';
WHEN 'E_DEADLINE' THEN SIGNAL SQLSTATE '45008' SET MESSAGE_TEXT='E_DEADLINE: Issue bounty deadline has elapsed.';
WHEN 'E_STATE' THEN SIGNAL SQLSTATE '45009' SET MESSAGE_TEXT='E_STATE: State transition is not permitted.';
WHEN 'E_CLAIM' THEN SIGNAL SQLSTATE '45010' SET MESSAGE_TEXT='E_CLAIM: Issue already has an exclusive claim.';
WHEN 'E_CLAIM_EXPIRED' THEN SIGNAL SQLSTATE '45011' SET MESSAGE_TEXT='E_CLAIM_EXPIRED: Claim submission deadline has elapsed.';
WHEN 'E_PERCENT' THEN SIGNAL SQLSTATE '45012' SET MESSAGE_TEXT='E_PERCENT: Percentages must be positive and sum to 100.00.';
WHEN 'E_REVIEW' THEN SIGNAL SQLSTATE '45013' SET MESSAGE_TEXT='E_REVIEW: PR does not satisfy the review gate.';
WHEN 'E_ORDER' THEN SIGNAL SQLSTATE '45014' SET MESSAGE_TEXT='E_ORDER: Milestone predecessors are not released.';
WHEN 'E_EXTENSION' THEN SIGNAL SQLSTATE '45015' SET MESSAGE_TEXT='E_EXTENSION: Deadline extension is unavailable.';
WHEN 'E_WITHDRAWAL' THEN SIGNAL SQLSTATE '45016' SET MESSAGE_TEXT='E_WITHDRAWAL: Pledge is not eligible for voluntary withdrawal.';
WHEN 'E_DISPUTE' THEN SIGNAL SQLSTATE '45017' SET MESSAGE_TEXT='E_DISPUTE: Issue already has an open dispute.';
WHEN 'E_KEY_REUSE' THEN SIGNAL SQLSTATE '45018' SET MESSAGE_TEXT='E_KEY_REUSE: Operation key was used with a different request.';
WHEN 'E_INTEGRITY' THEN SIGNAL SQLSTATE '45019' SET MESSAGE_TEXT='E_INTEGRITY: Accounting reconciliation failed.';
WHEN 'E_OVERFLOW' THEN SIGNAL SQLSTATE '45020' SET MESSAGE_TEXT='E_OVERFLOW: Monetary result exceeds DECIMAL(12,2).';
WHEN 'E_IMMUTABLE' THEN SIGNAL SQLSTATE '45021' SET MESSAGE_TEXT='E_IMMUTABLE: Append-only record cannot be modified or deleted.';
WHEN 'E_AUDIT_CONTEXT' THEN SIGNAL SQLSTATE '45022' SET MESSAGE_TEXT='E_AUDIT_CONTEXT: Trusted actor and operation context is required.';
WHEN 'E_APPROVALS' THEN SIGNAL SQLSTATE '45023' SET MESSAGE_TEXT='E_APPROVALS: Required approvals must be an integer from 1 to 3.';
WHEN 'E_CONTENT' THEN SIGNAL SQLSTATE '45024' SET MESSAGE_TEXT='E_CONTENT: Content reference or document contract is invalid.';
WHEN 'E_TRANSACTION' THEN SIGNAL SQLSTATE '45025' SET MESSAGE_TEXT='E_TRANSACTION: Procedure requires ownership of a new transaction.';
WHEN 'E_RETRY' THEN SIGNAL SQLSTATE '45026' SET MESSAGE_TEXT='E_RETRY: Transaction retry limit reached.';
ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='E_INPUT'; END CASE; END$$
DELIMITER ;
